cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && for b in rachel monica phoebe joey chandler ross; do git log --format='%ct %H friend/'$b origin/friend/$b; done | sort -n | while read ts sha branch; do :; done; echo "---"; python3 - <<'PY'
import subprocess
branches=['rachel','monica','phoebe','joey','chandler','ross']
items=[]
for b in branches:
    out=subprocess.check_output(['git','log','--format=%ct|%H|%s', 'origin/friend/'+b], text=True)
    for line in out.strip().splitlines():
        ts,sha,subj=line.split('|',2)
        # get full message
        msg=subprocess.check_output(['git','log','-1','--format=%B', sha], text=True)
        if 'S07/E12' in msg:
            items.append((int(ts),sha,'friend/'+b,msg.strip()))
items.sort()
for ts,sha,br,msg in items:
    # extract speaker line
    for l in msg.splitlines():
        if l.startswith(('Rachel:','Monica:','Phoebe:','Joey:','Chandler:','Ross:')):
            print(f"{ts} {br} {sha[:12]} :: {l}")
PY
